# ! [doc = " The Rust Linkage Model and Symbol Names"] # ! [doc = " ======================================="] # ! [doc = ""] # ! [doc = " The semantic model of Rust linkage is, broadly, that \"there's no global"] # ! [doc = " namespace\" between crates. Our aim is to preserve the illusion of this"] # ! [doc = " model despite the fact that it's not *quite* possible to implement on"] # ! [doc = " modern linkers. We initially didn't use system linkers at all, but have"] # ! [doc = " been convinced of their utility."] # ! [doc = ""] # ! [doc = " There are a few issues to handle:"] # ! [doc = ""] # ! [doc = "  - Linkers operate on a flat namespace, so we have to flatten names."] # ! [doc = "    We do this using the C++ namespace-mangling technique. Foo::bar"] # ! [doc = "    symbols and such."] # ! [doc = ""] # ! [doc = "  - Symbols for distinct items with the same *name* need to get different"] # ! [doc = "    linkage-names. Examples of this are monomorphizations of functions or"] # ! [doc = "    items within anonymous scopes that end up having the same path."] # ! [doc = ""] # ! [doc = "  - Symbols in different crates but with same names \"within\" the crate need"] # ! [doc = "    to get different linkage-names."] # ! [doc = ""] # ! [doc = "  - Symbol names should be deterministic: Two consecutive runs of the"] # ! [doc = "    compiler over the same code base should produce the same symbol names for"] # ! [doc = "    the same items."] # ! [doc = ""] # ! [doc = "  - Symbol names should not depend on any global properties of the code base,"] # ! [doc = "    so that small modifications to the code base do not result in all symbols"] # ! [doc = "    changing. In previous versions of the compiler, symbol names incorporated"] # ! [doc = "    the SVH (Stable Version Hash) of the crate. This scheme turned out to be"] # ! [doc = "    infeasible when used in conjunction with incremental compilation because"] # ! [doc = "    small code changes would invalidate all symbols generated previously."] # ! [doc = ""] # ! [doc = "  - Even symbols from different versions of the same crate should be able to"] # ! [doc = "    live next to each other without conflict."] # ! [doc = ""] # ! [doc = " In order to fulfill the above requirements the following scheme is used by"] # ! [doc = " the compiler:"] # ! [doc = ""] # ! [doc = " The main tool for avoiding naming conflicts is the incorporation of a 64-bit"] # ! [doc = " hash value into every exported symbol name. Anything that makes a difference"] # ! [doc = " to the symbol being named, but does not show up in the regular path needs to"] # ! [doc = " be fed into this hash:"] # ! [doc = ""] # ! [doc = " - Different monomorphizations of the same item have the same path but differ"] # ! [doc = "   in their concrete type parameters, so these parameters are part of the"] # ! [doc = "   data being digested for the symbol hash."] # ! [doc = ""] # ! [doc = " - Rust allows items to be defined in anonymous scopes, such as in"] # ! [doc = "   `fn foo() { { fn bar() {} } { fn bar() {} } }`. Both `bar` functions have"] # ! [doc = "   the path `foo::bar`, since the anonymous scopes do not contribute to the"] # ! [doc = "   path of an item. The compiler already handles this case via so-called"] # ! [doc = "   disambiguating `DefPaths` which use indices to distinguish items with the"] # ! [doc = "   same name. The DefPaths of the functions above are thus `foo[0]::bar[0]`"] # ! [doc = "   and `foo[0]::bar[1]`. In order to incorporate this disambiguation"] # ! [doc = "   information into the symbol name too, these indices are fed into the"] # ! [doc = "   symbol hash, so that the above two symbols would end up with different"] # ! [doc = "   hash values."] # ! [doc = ""] # ! [doc = " The two measures described above suffice to avoid intra-crate conflicts. In"] # ! [doc = " order to also avoid inter-crate conflicts two more measures are taken:"] # ! [doc = ""] # ! [doc = " - The name of the crate containing the symbol is prepended to the symbol"] # ! [doc = "   name, i.e., symbols are \"crate qualified\". For example, a function `foo` in"] # ! [doc = "   module `bar` in crate `baz` would get a symbol name like"] # ! [doc = "   `baz::bar::foo::{hash}` instead of just `bar::foo::{hash}`. This avoids"] # ! [doc = "   simple conflicts between functions from different crates."] # ! [doc = ""] # ! [doc = " - In order to be able to also use symbols from two versions of the same"] # ! [doc = "   crate (which naturally also have the same name), a stronger measure is"] # ! [doc = "   required: The compiler accepts an arbitrary \"disambiguator\" value via the"] # ! [doc = "   `-C metadata` command-line argument. This disambiguator is then fed into"] # ! [doc = "   the symbol hash of every exported item. Consequently, the symbols in two"] # ! [doc = "   identical crates but with different disambiguators are not in conflict"] # ! [doc = "   with each other. This facility is mainly intended to be used by build"] # ! [doc = "   tools like Cargo."] # ! [doc = ""] # ! [doc = " A note on symbol name stability"] # ! [doc = " -------------------------------"] # ! [doc = " Previous versions of the compiler resorted to feeding NodeIds into the"] # ! [doc = " symbol hash in order to disambiguate between items with the same path. The"] # ! [doc = " current version of the name generation algorithm takes great care not to do"] # ! [doc = " that, since NodeIds are notoriously unstable: A small change to the"] # ! [doc = " code base will offset all NodeIds after the change and thus, much as using"] # ! [doc = " the SVH in the hash, invalidate an unbounded number of symbol names. This"] # ! [doc = " makes re-using previously compiled code for incremental compilation"] # ! [doc = " virtually impossible. Thus, symbol hash generation exclusively relies on"] # ! [doc = " DefPaths which are much more robust in the face of changes to the code base."] # ! [allow (internal_features)] # ! [doc (html_root_url = "https://doc.rust-lang.org/nightly/nightly-rustc/")] # ! [doc (rust_logo)] # ! [feature (assert_matches)] # ! [feature (rustdoc_internals)] use split_decls_genesis :: ourprelude :: * ; use rustc_hir :: def :: DefKind ; use rustc_hir :: def_id :: { CrateNum , LOCAL_CRATE } ; use rustc_middle :: middle :: codegen_fn_attrs :: { CodegenFnAttrFlags , CodegenFnAttrs } ; use rustc_middle :: mir :: mono :: { InstantiationMode , MonoItem } ; use rustc_middle :: query :: Providers ; use rustc_middle :: ty :: { self , Instance , TyCtxt } ; use rustc_session :: config :: SymbolManglingVersion ; use tracing :: debug ; mod export ; mod hashed ; mod legacy ; mod v0 ; pub mod errors ; pub mod test ; pub use v0 :: mangle_internal_symbol ; #[doc = " This function computes the symbol name for the given `instance` and the"] #[doc = " given instantiating crate. That is, if you know that instance X is"] #[doc = " instantiated in crate Y, this is the symbol name this instance would have."] pub fn symbol_name_for_instance_in_crate < 'tcx > (tcx : TyCtxt < 'tcx > , instance : Instance < 'tcx > , instantiating_crate : CrateNum ,) -> String { compute_symbol_name (tcx , instance , | | instantiating_crate) } pub fn provide (providers : & mut Providers) { * providers = Providers { symbol_name : symbol_name_provider , .. * providers } ; } fn symbol_name_provider < 'tcx > (tcx : TyCtxt < 'tcx > , instance : Instance < 'tcx >) -> ty :: SymbolName < 'tcx > { let symbol_name = compute_symbol_name (tcx , instance , | | { if is_generic (instance) { instance . upstream_monomorphization (tcx) . unwrap_or (LOCAL_CRATE) } else { LOCAL_CRATE } }) ; ty :: SymbolName :: new (tcx , & symbol_name) } pub fn typeid_for_trait_ref < 'tcx > (tcx : TyCtxt < 'tcx > , trait_ref : ty :: ExistentialTraitRef < 'tcx > ,) -> String { v0 :: mangle_typeid_for_trait_ref (tcx , trait_ref) } #[doc = " Computes the symbol name for the given instance. This function will call"] #[doc = " `compute_instantiating_crate` if it needs to factor the instantiating crate"] #[doc = " into the symbol name."] fn compute_symbol_name < 'tcx > (tcx : TyCtxt < 'tcx > , instance : Instance < 'tcx > , compute_instantiating_crate : impl FnOnce () -> CrateNum ,) -> String { let def_id = instance . def_id () ; let args = instance . args ; debug ! ("symbol_name(def_id={:?}, args={:?})" , def_id , args) ; if let Some (def_id) = def_id . as_local () { if tcx . proc_macro_decls_static (()) == Some (def_id) { let stable_crate_id = tcx . stable_crate_id (LOCAL_CRATE) ; return tcx . sess . generate_proc_macro_decls_symbol (stable_crate_id) ; } } let attrs = if tcx . def_kind (def_id) . has_codegen_attrs () { & tcx . codegen_instance_attrs (instance . def) } else { CodegenFnAttrs :: EMPTY } ; if attrs . flags . contains (CodegenFnAttrFlags :: RUSTC_STD_INTERNAL_SYMBOL) { let name = if let Some (name) = attrs . symbol_name { name } else { tcx . item_name (def_id) } ; return v0 :: mangle_internal_symbol (tcx , name . as_str ()) ; } let wasm_import_module_exception_force_mangling = { tcx . is_foreign_item (def_id) && tcx . sess . target . is_like_wasm && tcx . wasm_import_module_map (def_id . krate) . contains_key (& def_id . into ()) } ; if ! wasm_import_module_exception_force_mangling { if let Some (name) = attrs . symbol_name { return name . to_string () ; } if attrs . flags . contains (CodegenFnAttrFlags :: NO_MANGLE) { return tcx . item_name (def_id) . to_string () ; } } let is_globally_shared_function = matches ! (tcx . def_kind (instance . def_id ()) , DefKind :: Fn | DefKind :: AssocFn | DefKind :: Closure | DefKind :: SyntheticCoroutineBody | DefKind :: Ctor (..)) && matches ! (MonoItem :: Fn (instance) . instantiation_mode (tcx) , InstantiationMode :: GloballyShared { may_conflict : true }) ; let avoid_cross_crate_conflicts = is_generic (instance) || is_globally_shared_function ; let instantiating_crate = avoid_cross_crate_conflicts . then (compute_instantiating_crate) ; let mangling_version_crate = instantiating_crate . unwrap_or (def_id . krate) ; let mangling_version = if mangling_version_crate == LOCAL_CRATE { tcx . sess . opts . get_symbol_mangling_version () } else { tcx . symbol_mangling_version (mangling_version_crate) } ; let symbol = match tcx . is_exportable (def_id) { true => format ! ("{}.{}" , v0 :: mangle (tcx , instance , instantiating_crate , true) , export :: compute_hash_of_export_fn (tcx , instance)) , false => match mangling_version { SymbolManglingVersion :: Legacy => legacy :: mangle (tcx , instance , instantiating_crate) , SymbolManglingVersion :: V0 => v0 :: mangle (tcx , instance , instantiating_crate , false) , SymbolManglingVersion :: Hashed => { hashed :: mangle (tcx , instance , instantiating_crate , | | { v0 :: mangle (tcx , instance , instantiating_crate , false) }) } } , } ; debug_assert ! (rustc_demangle :: try_demangle (& symbol) . is_ok () , "compute_symbol_name: `{symbol}` cannot be demangled") ; symbol } fn is_generic < 'tcx > (instance : Instance < 'tcx >) -> bool { instance . args . non_erasable_generics () . next () . is_some () }